def monday_of(d):
    return d - timedelta(days=d.weekday())

def money(value):
    return f"€ {value:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

def parse_time(value):
    value = value.strip()
    if not value:
        return None
    # Een heel uur mag kort worden ingevoerd: "8" betekent "08:00".
    if re.fullmatch(r"\d{1,2}", value):
        hour = int(value)
        if 0 <= hour <= 23:
            return datetime.strptime(f"{hour:02d}:00", "%H:%M")
    for fmt in ("%H:%M", "%H.%M"):
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            pass
    raise ValueError(f"Ongeldig tijdstip: {value}. Gebruik bijvoorbeeld 8 of 8:30.")

def hours_between(start, end):
    a, b = parse_time(start), parse_time(end)
    if a is None or b is None:
        return 0.0
    minutes = (b - a).total_seconds() / 60
    if minutes < 0:
        minutes += 24 * 60
    return minutes / 60

NTFY_URL = "https://ntfy.sh/"
WIDGET_TOPIC = "wu-widget-4e91c7a2b8d60f35"   # zelfde topic als de Scriptable-widget
CODE_ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789"


def utc_iso():
    """Tijdstempel in UTC, zelfde formaat als de telefoon-app (JSON-tekst vergelijkbaar)."""
    d = datetime.now(timezone.utc)
    return d.strftime("%Y-%m-%dT%H:%M:%S.") + f"{d.microsecond // 1000:03d}Z"


def ntfy_seal(raw, k_enc, k_mac):
    """Versleutel bytes (zelfde methode als de telefoon-app); geeft base64-tekst terug."""
    nonce = secrets.token_bytes(16)
    ct = bytearray()
    for i in range((len(raw) + 31) // 32):
        ks = hmac.new(k_enc, nonce + i.to_bytes(4, "big"), hashlib.sha256).digest()
        ct += bytes(a ^ b for a, b in zip(raw[i * 32:(i + 1) * 32], ks))
    ct = bytes(ct)
    return base64.b64encode(nonce + hmac.new(k_mac, nonce + ct, hashlib.sha256).digest() + ct).decode("ascii")


def ntfy_keys(code, sfx=""):
    """Leid topic en sleutels af uit de koppelcode; sfx "-pc" is het kanaal pc -> telefoon."""
    sec = code.encode("utf-8")
    h = lambda label: hmac.new(sec, label + sfx.encode(), hashlib.sha256).digest()
    return "wu-" + h(b"topic")[:16].hex(), h(b"enc"), h(b"mac")


def ntfy_open(blob_b64, k_enc, k_mac):
    """Controleer (HMAC) en ontcijfer een bericht van de telefoon; geeft het JSON-object terug."""
    raw = base64.b64decode(blob_b64)
    if len(raw) < 49:
        raise ValueError("te kort")
    nonce, tag, ct = raw[:16], raw[16:48], raw[48:]
    if not hmac.compare_digest(tag, hmac.new(k_mac, nonce + ct, hashlib.sha256).digest()):
        raise ValueError("ongeldige handtekening")
    out = bytearray()
    for i in range((len(ct) + 31) // 32):
        ks = hmac.new(k_enc, nonce + i.to_bytes(4, "big"), hashlib.sha256).digest()
        out += bytes(a ^ b for a, b in zip(ct[i * 32:(i + 1) * 32], ks))
    out = bytes(out)
    if out[:2] == b"\x1f\x8b":
        out = gzip.decompress(out)
    return json.loads(out.decode("utf-8"))


