        # Open automatically maximized on Windows; retain a normal-size fallback.
        try:
            self.root.state("zoomed")
        except tk.TclError:
            pass
        self.root.configure(bg="#eef2f7")
        self.records = {}
        self.deleted = {}          # verwijdermarkeringen, ook naar de telefoon
        self.rate = DEFAULT_RATE
        self._autosave_after_id = None
